import React, { useEffect, useState } from "react";

export default function UserProfileCard({ me = {}, activities = [], token, setMsg }) {

  // ADDED: Local state to store user info
  const [user, setUser] = useState(me);

  // ADDED: Fetch logged-in user details
  useEffect(() => {
    if (!token) return;

    (async () => {
      try {
        const res = await fetch(
          (process.env.REACT_APP_API || "http://localhost:4000") + "/api/me",
          {
            headers: { Authorization: `Bearer ${token}` },
          }
        );
        const d = await res.json();
        setUser(d.user || d); // update user state
      } catch (e) {
        if (setMsg) setMsg("Failed to load profile");
      }
    })();
  }, [token]);

  // Default avatar image
  const defaultAvatar =
    "https://cdn-icons-png.flaticon.com/512/149/149071.png"; // generic user icon

  return (
    <div
      style={{
        background: "#fff",
        padding: 16,
        borderRadius: 10,
        textAlign: "center",
        boxShadow: "0 4px 12px rgba(0,0,0,0.05)",
      }}
    >
      {/* Profile Icon */}
      <div
        style={{
          width: 70,
          height: 70,
          borderRadius: "50%",
          overflow: "hidden",
          margin: "0 auto 10px",
        }}
      >
        <img
          src={user?.profileImage || defaultAvatar}
          alt="Profile"
          style={{ width: "100%", height: "100%", objectFit: "cover" }}
        />
      </div>

      <div style={{ fontWeight: "bold", fontSize: 16 }}>{user?.name || "No Name"}</div>
      <div style={{ fontSize: 13, color: "#666", marginBottom: 4 }}>{user?.email || "No Email"}</div>
      <div style={{ fontSize: 13, color: "#666", marginBottom: 8 }}>Role: {user?.role || "Member"}</div>
    </div>
  );
}
